/**
 * ═══ THE NATIONAL LIST OF ESSENTIAL MEDICINES 2022, TRANSCRIBED ═══
 *
 * Source: Ministry of Health and Family Welfare, Government of India — "National List of Essential
 * Medicines 2022" (NLEM 2022), released 13 September 2022: 384 medicines in 27 therapeutic sections.
 * The copy transcribed is the one CDSCO publishes:
 *   https://cdsco.gov.in/opencms/resources/UploadCDSCOWeb/2018/UploadConsumer/nlem2022.pdf
 *   sha256 17dfa27760a73cee226392109a4e96f2594921431cfd6b7a8acfe8eab5e01533 (fetched 2026-09-22)
 *
 * How it was transcribed: `pdftotext -raw` (reading order keeps each table cell whole) parsed into
 * one row per printed dosage-form-and-strength line, then reviewed by hand section by section against
 * `pdftotext -layout`, and cross-checked against the list's own "Alphabetical List of Medicines in
 * NLEM 2022": every one of its 384 names is here and nothing else is. Codes run without a gap in every
 * subsection.
 *
 * What was normalised, and nothing else:
 *   - footnote markers (`*`, `**`, `#`) are stripped from names; the footnotes themselves ("also listed
 *     in Section …", "# for prophylaxis of P. vivax", the MDI/DPI legend) are not rows;
 *   - the component markers `(A)`, `(B)`, `(C)` are stripped from names and strengths, so a combination
 *     reads "Amoxicillin + Clavulanic acid" / "500 mg + 125 mg";
 *   - `(p)` (a paediatric formulation) becomes `paediatric: true` and leaves the strength;
 *   - a "Modified Release -" heading over several tablet lines is written onto each line;
 *   - the level of healthcare is the one printed beside THAT line (e.g. amoxicillin + clavulanic acid is
 *     P,S,T orally and S,T as an injection);
 *   - the three sub-items the list prints under one medicine are one row each: Amphotericin B
 *     (conventional / lipid / liposomal), Snake venom antiserum (liquid / lyophilised), and Ferrous salts
 *     (the tablet, iron dextran and iron sorbitol citrate complex injections);
 *   - levothyroxine's strength-range footnote is dropped from its strength ("12.5 mcg to 150 mcg").
 * `form` is OUR classification of the printed `formText`, for matching; `formText` is the document's.
 * Cross-listed medicines (paracetamol in 2.1.5, 5.2.3 and 27.4) appear in every section that prints them.
 *
 * Counts: 951 rows; 459 section entries (codes); 386 distinct medicine names = the 384 medicines
 * plus the two ferrous-salt injections named on their own rows. Rows per form: tablet 395, injection 266, oral_liquid 86, capsule 70, other 50, eye_drops 19, inhalation 16, topical_other 11, nasal 8, cream 8, suppository 5, powder 4, ointment 3, lotion 3, eye_ointment 3, gel 2, ear_drops 2.
 * Paediatric rows: 75.
 */
export const NLEM_2022_SOURCE = {
  title: "National List of Essential Medicines 2022",
  publisher: "Ministry of Health and Family Welfare, Government of India",
  url: "https://cdsco.gov.in/opencms/resources/UploadCDSCOWeb/2018/UploadConsumer/nlem2022.pdf",
  sha256: "17dfa27760a73cee226392109a4e96f2594921431cfd6b7a8acfe8eab5e01533",
  medicines: 384,
} as const;

export type NlemForm =
  | "tablet"
  | "capsule"
  | "oral_liquid"
  | "injection"
  | "cream"
  | "ointment"
  | "gel"
  | "lotion"
  | "eye_drops"
  | "eye_ointment"
  | "ear_drops"
  | "nasal"
  | "inhalation"
  | "suppository"
  | "powder"
  | "topical_other"
  | "other";

export type NlemEntry = {
  /** The list's own number, e.g. "2.1.5". */
  code: string;
  /** As printed, footnote asterisks and (A)/(B) markers stripped, e.g. "Amoxicillin + Clavulanic acid". */
  medicine: string;
  /** The dosage-form text as printed, e.g. "Tablet", "Oral liquid", "Dispersible Tablet". */
  formText: string;
  form: NlemForm;
  /** As printed, e.g. "500 mg", "120 mg/5 mL", "300 mg to 500 mg", "500 mg + 125 mg"; "" when none is printed. */
  strength: string;
  /** Level of healthcare: P primary, S secondary, T tertiary, e.g. "P,S,T". */
  level: string;
  /** Printed with "(p)": a paediatric formulation. */
  paediatric: boolean;
};

